const [commandError, setCommandError] = useState<string | null>(null);
const [confirmChatRestore, setConfirmChatRestore] = useState(false);
// Whether the thread is scrolled under the pinned setup band, which then
// lifts off it.
const [threadScrolled, setThreadScrolled] = useState(false);
// Where the full setup offer was at the last render, so the setup bar that
// replaces it can start from there.
const offerRef = useRef<HTMLDivElement>(null);
const offerRect = useRef<DOMRect | null>(null);
const [lowNoticeDone, setLowNoticeDone] = useState(false);
// "+1,000 credits" over the message box once the sheet the composer opened
// has closed on a purchase: the balance before the click, then what the
// account answer read after it added.
const balanceBeforeSheet = useRef<number | null>(null);
const [creditsAdded, setCreditsAdded] = useState<number | null>(null);
useLayoutEffect(() => { offerRect.current = offerRef.current?.getBoundingClientRect() ?? null; });

const client = useMemo(() => {
  const created: BridgeClient = new BridgeClient({
    getTransport,
    handshakeTimeoutMs,
    transportRetryMs,
    transportRetryLimit,
    onConnectionChange: (connection, detail) => dispatch({ kind: 'connection', state: connection, detail }),
    onEnvelope: (envelope: Envelope) => {
      if (envelope.type === 'bridge_error') {
        const payload = envelope.payload as { code?: string; message?: string };
        setCommandError(payload.message ?? 'The action could not be completed.');
        // The host restarts after a reload on its side; if it forgot us,
        // simply shake hands again.
        if (payload.code === 'handshake_required') created.retry();
      }
      dispatch({ kind: 'host', envelope });
    },
  });
  return created;
  // The transport is fixed for the lifetime of the page.
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, []);

useEffect(() => {
  client.start();
}, [client]);

useEffect(() => {
  applyAppearance(state.appearance);
}, [state.appearance]);

// The shell's own Ctrl+, cannot see keys while this page has the focus.
// The printer conversation has no shell behind it that would answer.
