  }""","""  start(): void {
    if (typeof window !== 'undefined') {
      window.__jusprinBridge = { deliver: (envelope: unknown) => this.deliver(envelope) };
      // The web view can keep this document in its back-forward cache when
      // it navigates away, such as to a file dropped on it, and bring it back
      // as it was without loading it again. Only the page sees either.
      window.addEventListener('pagehide', () => {
        if (this.protocol.pageHiddenType) this.post(this.protocol.pageHiddenType, {});
      });
      window.addEventListener('pageshow', (event) => {
        if ((event as PageTransitionEvent).persisted) this.handshakeAgain();
      });
    }
    this.beginHandshake();
  }

  // A document back from the cache missed what the host sent while it was
  // away. A connected page stays on screen while the new hello brings the
  // host's whole state again.
  private handshakeAgain(): void {
    if (this.state === 'connected' && this.transport) this.post('hello', this.helloPayload());
    else this.retry();
  }

  private helloPayload() {
    return { protocolVersions: [this.protocol.version], capabilities: this.protocol.capabilities };
  }""")
